package com.myeshopping.returnrefundservice;
import com.fasterxml.jackson.databind.ObjectMapper; import com.myeshopping.returnrefundservice.dto.ReturnRequest; import com.myeshopping.returnrefundservice.dto.TransitionRequest; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
@SpringBootTest @AutoConfigureMockMvc class ReturnRefundServiceApplicationTests { @Autowired MockMvc mockMvc; @Autowired ObjectMapper mapper; @Test void returnAndRefundLifecycleShouldWork() throws Exception { ReturnRequest request=new ReturnRequest();request.setOrderId(2001L);request.setCustomerId(1001L);request.setReason("Damaged item");request.setAmount(39.0); String body=mockMvc.perform(post("/api/v1/returns").contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(request))).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("RETURN_REQUESTED")).andReturn().getResponse().getContentAsString();long id=mapper.readTree(body).path("data").path("id").asLong();TransitionRequest transition=new TransitionRequest();transition.setStatus("RETURN_APPROVED");mockMvc.perform(post("/api/v1/returns/"+id+"/transition").contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(transition))).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("RETURN_APPROVED"));transition.setStatus("RETURN_PICKUP_PENDING");mockMvc.perform(post("/api/v1/returns/"+id+"/transition").contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(transition))).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("RETURN_PICKUP_PENDING"));transition.setStatus("RETURNED");mockMvc.perform(post("/api/v1/returns/"+id+"/transition").contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(transition))).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("RETURNED"));TransitionRequest refund=new TransitionRequest();refund.setStatus("REFUND_PROCESSING");mockMvc.perform(post("/api/v1/returns/"+id+"/refund").contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(refund))).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("REFUND_PROCESSING"));} }
